      name: 'Venus Cloud City', short: 'a city floating in the clouds of Venus', in: 'in a city floating high in the clouds of Venus', era: 'future', tags: ['space', 'sky', 'tech', 'warm'],
      towns: ['AEROSTAT ONE', 'GOLDEN HAZE', 'THE GONDOLA', 'CLOUD DOCK', 'HIGH BALLOON', 'SULPHUR VIEW', 'TERMINATOR', 'THE ENVELOPE', 'MORNING STAR'],
